-- Function: public.fn_get_emergency_contacts
-- Backup generated on 2026-10-25 20:33:15

CREATE OR REPLACE FUNCTION public.fn_get_emergency_contacts(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_active_only boolean DEFAULT false)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, scope character varying, category character varying, name character varying, phone_number character varying, alternate_phone_number character varying, country_region character varying, address text, instructions text, verification_status character varying, verified_by character varying, verified_at timestamp with time zone, review_due_at timestamp with time zone, is_active boolean, display_order integer, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, organization_id, branch_id, scope, category,         name, phone_number, alternate_phone_number, country_region, address,         instructions, verification_status, verified_by, verified_at,         review_due_at, is_active, display_order, created_at, updated_at     FROM emergency_contacts     WHERE tenant_id = p_tenant_id       AND (NOT p_active_only OR is_active = TRUE)       AND (           scope = 'Jurisdiction'           OR (scope = 'Organization' AND (p_organization_id IS NULL OR organization_id IS NULL OR organization_id = p_organization_id))           OR (scope = 'Branch' AND (p_branch_id IS NULL OR branch_id IS NULL OR branch_id = p_branch_id))       )     ORDER BY display_order ASC, name ASC; $function$ ;
